20	const SNAPSHOT_EVENT = 'agent-status:snapshot';
21	const INSTALL_STATE_EVENT = 'agent-status:install-state';   // tool → panel：接入与否
22	const INSTALL_CLAUDE_EVENT = 'agent-status:install-claude';   // panel → tool：接入意图
23	const UNINSTALL_CLAUDE_EVENT = 'agent-status:uninstall-claude'; // panel → tool：移除意图
24	
25	// 进程存活探测：kill(pid, 0) 不发信号只查存在性。EPERM = 存在但不属于本用户，算存活。
26	function isPidAlive(pid) {
27	  try { process.kill(pid, 0); return true; } catch (err) { return err && err.code === 'EPERM'; }
28	}
29	
30	/**
31	 * 造一个采集器。所有外部依赖可注入，测试不碰真实目录/时钟/进程。
32	 * @param {object} [deps] { dir, now, isPidAlive, t, playAnimGuard, readSnapshots }
33	 */
34	function createCollector(deps) {
35	  const d = deps || {};
36	  const readSnapshots = typeof d.readSnapshots === 'function' ? d.readSnapshots : stateFiles.readSnapshots;
37	  const now = typeof d.now === 'function' ? d.now : () => Date.now();
38	  const alive = typeof d.isPidAlive === 'function' ? d.isPidAlive : isPidAlive;
39	  // 语言只认这一处。副行/时间文案由 tool 取词后随行下发，panel 的静态文案则按
40	  // 快照里带的 locale 取 —— 两边各猜各的会当场撞车：tool 看 LANG、panel 看
41	  // navigator.language，两者不一致时同一块面板上半截中文下半截英文。
42	  const i18n = createNodeI18n(d.locale);
43	  const t = typeof d.t === 'function' ? d.t : i18n.t;
44	  const locale = d.locale || i18n.locale;
45	  const link = createPetLink({ playAnimGuard: d.playAnimGuard });
46	  // 缺省 undefined → installer 自己走 settingsPath()（即 PET_AS_CLAUDE_SETTINGS 覆盖）；
47	  // 测试注入临时文件，绝不碰真实 ~/.claude/settings.json
48	  const installOpts = d.settingsFile ? { settingsFile: d.settingsFile } : undefined;
49	
50	  let taskId = null;
51	  let lastSnapshot = { rows: [], summary: { running: 0, waiting: 0, total: 0, unknown: 0 } };
