60	      result.locale = locale;
61	      lastSnapshot = result;
62	      emit(pet, SNAPSHOT_EVENT, result);
63	      // 接入态随每轮一起推：面板是随开随关的，start 时推一次的话，
64	      // 之后才打开的面板永远等不到这条，空态会一直停在「一键接入」——
65	      // 哪怕钩子早就装好了。读一个小 JSON，2s 一次的开销可以忽略。
66	      pushInstallState(pet);
67	      link.onSnapshot(result.rows, pet, { now: at, t });
68	      return result;
69	    } catch (_) {
70	      return lastSnapshot;   // 本轮读坏了就沿用上轮，面板不闪空
71	    }
72	  }
73	
74	  // panel 的接入按钮只发意图，改配置的活在这边（panel 上下文没有 fs，也不该有）。
75	  // 每次改完立刻回推一次接入态，面板的「一键接入 / 已接入 ✓」当场翻面。
76	  function pushInstallState(pet) {
77	    let claude = false;
78	    try { claude = installer.isInstalled(installOpts); } catch (_) { claude = false; }
79	    emit(pet, INSTALL_STATE_EVENT, { claude });
80	    return claude;
81	  }
82	
83	  function handleInstall(pet) {
84	    // 改用户 settings.json 失败不该打死采集器：面板照旧显示「未接入」，用户可再试。
85	    try { installer.install(installOpts); } catch (_) { /* 权限/磁盘问题 */ }
86	    return pushInstallState(pet);
87	  }
88	
89	  function handleUninstall(pet) {
90	    try { installer.uninstall(installOpts); } catch (_) { /* 同上 */ }
91	    return pushInstallState(pet);
92	  }
93	
94	  async function start(pet) {
95	    if (taskId != null) return taskId;   // 启停串行，不重复注册（重复注册 = 泄漏定时器）
96	    // 先接意图再起定时器：面板可能在 tick 之前就点了接入
97	    subscribe(pet, INSTALL_CLAUDE_EVENT, () => handleInstall(pet));
98	    subscribe(pet, UNINSTALL_CLAUDE_EVENT, () => handleUninstall(pet));
