102	    tick(pet);   // 立刻来一轮，用户开面板不用等 2 秒
103	    return taskId;
104	  }
105	
106	  async function stop(pet) {
107	    if (taskId == null) return;
108	    const id = taskId;
109	    taskId = null;   // 先清再 cancel：cancel 失败也不该留个假 id 挡住下次 start
110	    try { await pet.scheduler.cancel(id); } catch (_) { /* 宿主已经收走了 */ }
111	  }
112	
113	  return {
114	    start, stop, tick,
115	    handleInstall, handleUninstall, pushInstallState,
116	    get taskId() { return taskId; },
117	    get lastSnapshot() { return lastSnapshot; }
118	  };
119	}
120	
121	function emit(pet, name, data) {
122	  try {
123	    if (pet && pet.events && typeof pet.events.emit === 'function') pet.events.emit(name, data);
124	  } catch (_) { /* 面板没开着，推送失败无所谓 */ }
125	}
126	
127	// 订阅 panel 发来的意图。回调整体包 try/catch：panel 送来什么都不该打死 tool。
128	function subscribe(pet, name, fn) {
129	  try {
130	    if (pet && pet.events && typeof pet.events.on === 'function') {
131	      pet.events.on(name, (data) => { try { fn(data); } catch (_) { /* 单次意图失败 */ } });
132	    }
133	  } catch (_) { /* 宿主没给 events 面 */ }
134	}
135	
136	let collector = null;
137	let activeSdk = null;
138	
139	async function activate(pet) {
140	  activeSdk = pet;
141	  collector = createCollector();
142	  await collector.start(pet);
143	  return collector;
144	}
145	
146	// 宿主当前是 kill 子进程 + 自动取消定时器（runtime.js#deactivateRec），没有调 deactivate 的路径；
147	// 这里仍显式实现，既是 criteria 要求，也为宿主将来接上这个钩子留好口子。
148	// pet 省略时用 activate 时存下的那个 —— 宿主多半不会再传一遍。
149	async function deactivate(pet) {
150	  if (!collector) return;
151	  await collector.stop(pet || activeSdk);
152	  collector = null;
153	  activeSdk = null;
154	}
155	
156	module.exports = {
157	  activate, deactivate, createCollector,
158	  isPidAlive, TICK_MS,
159	  SNAPSHOT_EVENT, INSTALL_STATE_EVENT, INSTALL_CLAUDE_EVENT, UNINSTALL_CLAUDE_EVENT
