1	'use strict';
2	// 采集器状态机：状态文件快照 → panel 渲染行（PROTOCOL.md「采集器推导态」的唯一实现处）。
3	//
4	// 全纯函数：now / isPidAlive 一律由调用方注入，测试不 sleep、不探真实进程。
5	// 推导态 error/idle/unknown 只活在这里与面板，绝不落盘（协议红线）。
6	
7	const ERROR_STALE_MS = 60 * 1000;        // running/waiting 超过这么久没心跳才考虑 error
8	const IDLE_MS = 20 * 60 * 1000;          // 任何状态超过这么久算 idle
9	const DROP_IDLE_MS = 20 * 60 * 1000;     // idle 超过这么久从面板移除
10	
11	// 副行文案的 locale key（DESIGN.md 状态图例；unknown 与 idle 必须不同词，绝不误报完成）
12	const SUBLINE_KEY = {
13	  running: 'state.running',
14	  waiting: 'state.waiting',
15	  done: 'state.done',
16	  ended: 'state.ended',
17	  error: 'state.error',
18	  idle: 'state.idle',
19	  unknown: 'state.unknown'
20	};
21	
22	// 会话形态：本轮只有 CLI（Codex App 任务是二期，见 docs/prd.md 非目标）
23	function formOf(rec) {
24	  return rec && rec.form === 'app' ? 'app' : 'cli';
25	}
26	
27	/**
28	 * 单条记录 → 展示态。落盘只有 running/waiting/done/ended 四种，其余都在这里推。
29	 * @param {object} rec 已通过 validateRecord 的记录
30	 * @param {number} now 注入的当前毫秒
31	 * @param {(pid:number)=>boolean} isPidAlive 注入的存活探测
32	 */
33	function deriveState(rec, now, isPidAlive) {
34	  const age = now - rec.ts;
35	  // error 优先于 idle：进程已经不在了，比「久没动静」更有信息量（PROTOCOL.md 推导态第 1 条）
36	  if ((rec.state === 'running' || rec.state === 'waiting')
37	      && age > ERROR_STALE_MS
38	      && rec.pid != null
39	      && !isPidAlive(rec.pid)) {
40	    return 'error';
41	  }
42	  if (rec.state === 'done' || rec.state === 'ended') return 'idle';
43	  if (age > IDLE_MS) return 'idle';
44	  return rec.state;
45	}
46	
47	// running 行显 mm:ss 计时（DESIGN.md 右列）；其余显相对时间
48	function formatTime(state, ageMs, t) {
49	  if (state === 'running' || state === 'waiting') {
50	    const total = Math.max(0, Math.floor(ageMs / 1000));
51	    const mm = String(Math.floor(total / 60)).padStart(2, '0');
52	    const ss = String(total % 60).padStart(2, '0');
53	    return `${mm}:${ss}`;
54	  }
55	  const minutes = Math.floor(Math.max(0, ageMs) / 60000);
56	  return minutes < 1 ? t('time.justNow') : t('time.minutesAgo', { n: minutes });
57	}
58	
59	/**
60	 * 这条记录是从哪一刻开始算 idle 的。
61	 *
62	 * 两种入 idle 的路径起点不同，不能都拿 ts 当起点：
63	 * - done/ended：写入那一刻就完成了，idle 从 `ts` 起算；
64	 * - running/waiting 熬过 20min：那 20min 里它还在「运行中」显示着，
65	 *   idle 从 `ts + IDLE_MS` 起算，否则一个刚超时的 running 会被当成
66	 *   「已经 idle 了 20 分钟」当场移除，用户眼前的行凭空消失。
67	 */
68	function idleSince(rec) {
69	  return (rec.state === 'done' || rec.state === 'ended') ? rec.ts : rec.ts + IDLE_MS;
70	}
71	
72	// 排序：waiting 恒置顶（组内 ts 降序），其余 ts 降序（DESIGN.md「排序规则」）
73	function sortRows(rows) {
74	  return rows.slice().sort((a, b) => {
75	    const aw = a.state === 'waiting' ? 0 : 1;
76	    const bw = b.state === 'waiting' ? 0 : 1;
77	    if (aw !== bw) return aw - bw;
78	    return b.ts - a.ts;
79	  });
80	}
81	
82	// 取词兜底：没注入 i18n 时返回 key，界面上一眼看出漏词（与 lib/i18n.js 同策略）
83	function fallbackT(key) { return key; }
84	
85	/**
86	 * 快照 → { rows, summary }。
87	 * @param {{records:object[], unknown?:object[]}} snapshot lib/state-files.js#readSnapshots 的返回值
88	 * @param {{now:number, isPidAlive:Function, t?:Function}} opts
89	 */
90	function aggregate(snapshot, opts) {
91	  const o = opts || {};
92	  const now = Number.isFinite(o.now) ? o.now : Date.now();
93	  const isPidAlive = typeof o.isPidAlive === 'function' ? o.isPidAlive : () => true;
