file.content:
.project{font-size:13px;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.subline{font-size:11px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.side{display:flex;align-items:center;gap:6px;flex:0 0 auto}
.dot{width:8px;height:8px;border-radius:50%}
.time{font-size:11px;color:var(--gray);font-family:"Inter",system-ui,sans-serif;
  font-variant-numeric:tabular-nums}
/* 状态色：副行与状态点同一档（DESIGN.md 状态图例） */
.state-running .subline{color:var(--running-sub)}
.state-running .dot{background:var(--primary)}
.state-waiting .subline{color:var(--warning)}
.state-waiting .dot{background:var(--warning)}
.state-done .subline{color:var(--success)}
.state-done .dot{background:var(--success)}
.state-error .subline{color:var(--danger)}
.state-error .dot{background:var(--danger)}
.state-idle .subline{color:var(--gray)}
.state-idle .dot{background:var(--gray)}
.state-unknown .subline{color:var(--gray)}
.state-unknown .dot{background:var(--gray)}
/* 跳转失败：行内错误条，不弹窗不静默（DESIGN.md） */
.jump-error{
  margin-top:6px;padding:5px 10px;border-radius:8px;
  background:rgba(235,87,87,.12);color:var(--danger);font-size:11px;
}
/* ---- 空态 ---- */
.empty{display:flex;flex-direction:column;align-items:center;text-align:center;padding:22px 8px 0}
.empty-icon{
  width:56px;height:56px;border-radius:50%;
  background:rgba(255,255,255,.06);color:var(--gray);
  display:flex;align-items:center;justify-content:center;
  font-size:17px;font-family:"Inter",ui-monospace,monospace;
}
.empty-title{margin-top:14px;font-size:14px;color:#fff}
.empty-desc{margin-top:8px;font-size:11px;color:var(--gray);line-height:1.7}
.install-btn{
  margin-top:18px;padding:9px 18px;border:0;border-radius:10px;
  background:var(--primary);color:#fff;font-size:12.5px;font-family:inherit;cursor:pointer;
}
.installed{margin-top:18px;font-size:12.5px;color:var(--success)}
.uninstall-btn{
  margin-top:8px;background:none;border:0;cursor:pointer;
  color:var(--gray);font-size:11px;font-family:inherit;text-decoration:underline;
}
/* Codex 未落地：灰字说明，**不是**按钮、不挂 click（DESIGN.md 禁假入口） */
.codex-soon{margin-top:14px;font-size:11px;color:var(--gray)}
.footer{margin-top:12px;font-size:10.5px;color:var(--gray);text-align:center}
[hidden]{display:none !important}
</style>
</head>
<body>
  <div class="topbar">
    <span class="title" id="title"></span>
    <span class="summary" id="summary" hidden><span class="summary-dot"></span><span id="summary-text"></span></span>
    <button class="close" id="close" type="button">✕</button>
  </div>

  <div class="list" id="list"></div>

  <div class="empty" id="empty" hidden>
    <div class="empty-icon">&gt;_</div>
    <div class="empty-title" id="empty-title"></div>
    <div class="empty-desc"><span id="empty-desc1"></span><br><span id="empty-desc2"></span></div>
    <button class="install-btn" id="install-claude" type="button"></button>
    <div class="installed" id="installed" hidden></div>
    <button class="uninstall-btn" id="uninstall-claude" type="button" hidden></button>
    <div class="codex-soon" id="codex-soon"></div>
  </div>

  <div class="footer" id="footer"></div>

