  // 空态的接入按钮态机：未接入 → 蓝主按钮；已接入 → 「已接入 ✓」+ 移除钩子
  function renderInstallState() {
    elInstall.hidden = installed;
    elInstalled.hidden = !installed;
    elUninstall.hidden = !installed;
  }

  on(EV_SNAPSHOT, function (snapshot) { render(snapshot); });
  on(EV_INSTALL_STATE, function (data) {
    installed = !!(data && data.claude);
    if (!elEmpty.hidden) renderInstallState();
  });

  // 首帧：先按空态渲染，等 tool 的第一份快照（tool 侧 start() 会立刻推一轮）
  render({ rows: [], summary: { running: 0 } });
})();
