2	// 状态迁移 → 宠物联动（DESIGN.md「宠物联动」节）。
3	//
4	// 只在**状态迁移**时提醒，不是每次 tick 都喊：采集器 2s 一轮，
5	// 按当前状态发就会变成每 2 秒一次气泡。
6	// 节流：同 (sessionId, state) 5 分钟内最多一次。
7	// now 注入，测试不 sleep。
8	
9	const THROTTLE_MS = 5 * 60 * 1000;
10	
11	// done → playAnim + bubble；waiting → 只 bubble（DESIGN.md）
12	//
13	// 动作名必须是**宿主认得的**那一批，否则静默丢弃：宿主 renderer.js 消费端写的是
14	// `if (s==='wake') {...} else if (ANIM[s] || STATE_FALLBACK[s]) setState(s);`
15	// —— 两个集合都不命中就什么都不做，无告警、无回落，动画在生产里等于没写。
16	// 合法全集见 HOST_ANIM_STATES（character-registry.js 的 STATE_DIR_NAME +
17	// renderer.js 的 STATE_FALLBACK）。
18	//
19	// 选 'unread'（未读信息）的理由：语义就是 DESIGN.md 说的「收到消息动画」，
20	// 且它同时在 ANIM 与 STATE_FALLBACK 里 —— 角色包缺这套素材时还能回落 idle。
21	const DONE_ANIM = 'unread';
22	
23	// 宿主合法动作名全集（只读快照，用于自检；宿主仓是只读参考，不 require 它）：
24	// - character-registry.js 的 STATE_DIR_NAME 键 = 角色动画目录名
25	// - renderer.js 的 STATE_FALLBACK 键 = 角色缺该动作时的替身（额外含 think）
26	const HOST_ANIM_STATES = Object.freeze([
27	  'idle', 'walk', 'sleep', 'wake', 'speak', 'send', 'drag', 'unread',
28	  'edgehide', 'peek', 'unpeek', 'greet', 'dropempty', 'dropfull', 'think'
29	]);
30	
31	/**
32	 * @param {{playAnimGuard?:()=>boolean}} [opts]
33	 *   playAnimGuard：宿主动画冲突（睡眠/被抓起）时返回 false → 降级为仅 bubble。
34	 *   本仓库拿不到宿主状态，缺省恒 true；接口必须存在，由宿主内真机验收定参。
35	 *   TODO(宿主真机验收)：接上宿主宠物状态后把守卫换成真实判定。
36	 */
37	function createPetLink(opts) {
38	  const o = opts || {};
39	  const guard = typeof o.playAnimGuard === 'function' ? o.playAnimGuard : () => true;
40	  const lastState = new Map();   // sessionId → 上一轮的展示态
41	  const lastNotify = new Map();  // `${sessionId}�${state}` → 上次提醒时刻
42	
43	  function throttled(sessionId, state, now) {
44	    const key = `${sessionId}�${state}`;
45	    const prev = lastNotify.get(key);
46	    if (prev != null && now - prev < THROTTLE_MS) return true;
47	    lastNotify.set(key, now);
48	    return false;
49	  }
50	
51	  /**
52	   * 吃一轮快照行，按迁移触发联动。
53	   * @param {object[]} rows aggregate 的 rows
54	   * @param {object} pet 宿主 SDK（可注入 mock；只用 pet.bubble / pet.playAnim）
55	   * @param {{now:number, t:Function}} ctx
56	   * @returns {object[]} 本轮真实触发的联动（供测试与诊断，不含被节流的）
57	   */
58	  function onSnapshot(rows, pet, ctx) {
59	    const now = Number.isFinite(ctx && ctx.now) ? ctx.now : Date.now();
60	    const t = (ctx && typeof ctx.t === 'function') ? ctx.t : (k) => k;
61	    const list = Array.isArray(rows) ? rows : [];
62	    const fired = [];
63	    const seen = new Set();
64	
65	    for (const row of list) {
66	      seen.add(row.sessionId);
67	      // 看 raw（落盘态）而不是 state（展示态）：done/ended 的展示态被推成 idle，
68	      // 只看 state 的话「差事办完啦」永远等不到 done，是死代码。
69	      const cur = rawOf(row);
70	      const prev = lastState.get(row.sessionId);
71	      lastState.set(row.sessionId, cur);
72	      if (prev === cur) continue;                             // 没迁移，不提醒
73	      if (cur !== 'done' && cur !== 'waiting') continue;
74	      // 首次见到就已是 done 的会话不提醒：那是插件启动前就结束的历史会话，
75	      // 现在喊「差事办完啦」是在报旧闻。waiting 首见要喊 —— 用户此刻真的被挡着。
76	      if (prev === undefined && cur === 'done') continue;
77	      if (throttled(row.sessionId, cur, now)) continue;
78	
79	      if (cur === 'done') {
80	        if (guard()) { call(pet, 'playAnim', DONE_ANIM); fired.push({ sessionId: row.sessionId, kind: 'playAnim' }); }
81	        const text = t('bubble.done', { project: row.project });
82	        call(pet, 'bubble', text);
83	        fired.push({ sessionId: row.sessionId, kind: 'bubble', state: 'done', text });
84	      } else {
85	        const text = t('bubble.waiting', { project: row.project });
86	        call(pet, 'bubble', text);
87	        fired.push({ sessionId: row.sessionId, kind: 'bubble', state: 'waiting', text });
88	      }
89	    }
90	
91	    // 会话行消失（idle 淡出/文件删除）后忘掉它，下次重现按首见处理，
92	    // 也顺手防 Map 无限长
93	    for (const id of [...lastState.keys()]) if (!seen.has(id)) lastState.delete(id);
94	    for (const key of [...lastNotify.keys()]) {
95	      if (now - lastNotify.get(key) >= THROTTLE_MS) lastNotify.delete(key);
96	    }
97	    return fired;
98	  }
99	
100	  return { onSnapshot, THROTTLE_MS };
101	}
102	
103	// 联动一律按落盘态判定。老快照（或测试）没带 raw 时回落到 state，
104	// 缺字段不至于让整条链路哑掉。
