110	// 方法在 `sdk.pet.*` 下（sdk-surface.js 的 ns='pet'），不是 sdk 顶层。
111	function call(sdk, method, arg) {
112	  try {
113	    const ns = sdk && sdk.pet;
114	    if (ns && typeof ns[method] === 'function') ns[method](arg);
115	  } catch (_) { /* 宿主拒绝/动画忙，面板照常更新 */ }
116	}
