// done → playAnim + bubble；waiting → 只 bubble（DESIGN.md）
//
// 动作名必须是**宿主认得的**那一批，否则静默丢弃：宿主 renderer.js 消费端写的是
// `if (s==='wake') {...} else if (ANIM[s] || STATE_FALLBACK[s]) setState(s);`
// —— 两个集合都不命中就什么都不做，无告警、无回落，动画在生产里等于没写。
// 合法全集见 HOST_ANIM_STATES（character-registry.js 的 STATE_DIR_NAME +
// renderer.js 的 STATE_FALLBACK）。
//
// 选 'unread'（未读信息）的理由：语义就是 DESIGN.md 说的「收到消息动画」，
// 且它同时在 ANIM 与 STATE_FALLBACK 里 —— 角色包缺这套素材时还能回落 idle。
const DONE_ANIM = 'unread';

// 宿主合法动作名全集（只读快照，用于自检；宿主仓是只读参考，不 require 它）：
// - character-registry.js 的 STATE_DIR_NAME 键 = 角色动画目录名
// - renderer.js 的 STATE_FALLBACK 键 = 角色缺该动作时的替身（额外含 think）
const HOST_ANIM_STATES = Object.freeze([
  'idle', 'walk', 'sleep', 'wake', 'speak', 'send', 'drag', 'unread',
  'edgehide', 'peek', 'unpeek', 'greet', 'dropempty', 'dropfull', 'think'
]);

/**
 * @param {{playAnimGuard?:()=>boolean}} [opts]
 *   playAnimGuard：宿主动画冲突（睡眠/被抓起）时返回 false → 降级为仅 bubble。
 *   本仓库拿不到宿主状态，缺省恒 true；接口必须存在，由宿主内真机验收定参。
 *   TODO(宿主真机验收)：接上宿主宠物状态后把守卫换成真实判定。
 */
function createPetLink(opts) {
  const o = opts || {};
  const guard = typeof o.playAnimGuard === 'function' ? o.playAnimGuard : () => true;
  const lastState = new Map();   // sessionId → 上一轮的展示态
  const lastNotify = new Map();  // `${sessionId}�${state}` → 上次提醒时刻

  function throttled(sessionId, state, now) {
    const key = `${sessionId}�${state}`;
    const prev = lastNotify.get(key);
    if (prev != null && now - prev < THROTTLE_MS) return true;
    lastNotify.set(key, now);
    return false;
  }

  /**
   * 吃一轮快照行，按迁移触发联动。
   * @param {object[]} rows aggregate 的 rows
   * @param {object} pet 宿主 SDK（可注入 mock；只用 pet.bubble / pet.playAnim）
   * @param {{now:number, t:Function}} ctx
   * @returns {object[]} 本轮真实触发的联动（供测试与诊断，不含被节流的）
   */
  function onSnapshot(rows, pet, ctx) {
    const now = Number.isFinite(ctx && ctx.now) ? ctx.now : Date.now();
    const t = (ctx && typeof ctx.t === 'function') ? ctx.t : (k) => k;
    const list = Array.isArray(rows) ? rows : [];
    const fired = [];
    const seen = new Set();

    for (const row of list) {
      seen.add(row.sessionId);
      // 看 raw（落盘态）而不是 state（展示态）：done/ended 的展示态被推成 idle，
      // 只看 state 的话「差事办完啦」永远等不到 done，是死代码。
      const cur = rawOf(row);
      const prev = lastState.get(row.sessionId);
      lastState.set(row.sessionId, cur);
      if (prev === cur) continue;                             // 没迁移，不提醒
      if (cur !== 'done' && cur !== 'waiting') continue;
      // 首次见到就已是 done 的会话不提醒：那是插件启动前就结束的历史会话，
      // 现在喊「差事办完啦」是在报旧闻。waiting 首见要喊 —— 用户此刻真的被挡着。
      if (prev === undefined && cur === 'done') continue;
      if (throttled(row.sessionId, cur, now)) continue;

      if (cur === 'done') {
        if (guard()) { call(pet, 'playAnim', DONE_ANIM); fired.push({ sessionId: row.sessionId, kind: 'playAnim' }); }
        const text = t('bubble.done', { project: row.project });
        call(pet, 'bubble', text);
        fired.push({ sessionId: row.sessionId, kind: 'bubble', state: 'done', text });
      } else {
        const text = t('bubble.waiting', { project: row.project });
        call(pet, 'bubble', text);
        fired.push({ sessionId: row.sessionId, kind: 'bubble', state: 'waiting', text });
      }
    }

    // 会话行消失（idle 淡出/文件删除）后忘掉它，下次重现按首见处理，
    // 也顺手防 Map 无限长
    for (const id of [...lastState.keys()]) if (!seen.has(id)) lastState.delete(id);
    for (const key of [...lastNotify.keys()]) {
      if (now - lastNotify.get(key) >= THROTTLE_MS) lastNotify.delete(key);
    }
    return fired;
  }

  return { onSnapshot, THROTTLE_MS };
}

// 联动一律按落盘态判定。老快照（或测试）没带 raw 时回落到 state，
// 缺字段不至于让整条链路哑掉。
function rawOf(row) {
  return (row && row.raw != null) ? row.raw : (row && row.state);
}

// 宠物联动失败绝不能打死采集器（下一轮还得跑）。
// 方法在 `sdk.pet.*` 下（sdk-surface.js 的 ns='pet'），不是 sdk 顶层。
function call(sdk, method, arg) {
  try {
    const ns = sdk && sdk.pet;
    if (ns && typeof ns[method] === 'function') ns[method](arg);
  } catch (_) { /* 宿主拒绝/动画忙，面板照常更新 */ }
}

module.exports = { THROTTLE_MS, DONE_ANIM, HOST_ANIM_STATES, createPetLink };

