const SUBLINE_KEY = {
  running: 'state.running',
  waiting: 'state.waiting',
  done: 'state.done',
  ended: 'state.ended',
  error: 'state.error',
  idle: 'state.idle',
  unknown: 'state.unknown'
};

// 会话形态：本轮只有 CLI（Codex App 任务是二期，见 docs/prd.md 非目标）
function formOf(rec) {
  return rec && rec.form === 'app' ? 'app' : 'cli';
}

