      result.locale = locale;
      lastSnapshot = result;
      emit(pet, SNAPSHOT_EVENT, result);
      // 接入态随每轮一起推：面板是随开随关的，start 时推一次的话，
      // 之后才打开的面板永远等不到这条，空态会一直停在「一键接入」——
