test('点会话行 → 发 agent-status:jump{sessionId}', () => {
  const snap = snapshotOf([
    rec({ sessionId: 'aaa', project: 'alpha', ts: T0 }),
    rec({ sessionId: 'bbb', project: 'beta', ts: T0 - 1000 })
  ]);
  const p = mountPanel();
  p.push('agent-status:snapshot', snap);
